import React, { useState, useEffect } from 'react';
import './App.css';

function App() {
  // --- ESTADOS DE AUTENTICACIÓN Y BLOQUEO ---
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');

  // --- ESTADOS DE PANTALLA ---
  const [pantalla, setPantalla] = useState('catalogo'); 
  const [productos, setProductos] = useState([]);

  // --- BÓVEDA DE IMÁGENES ---
  const [storedImages, setStoredImages] = useState(() => {
    const saved = localStorage.getItem('catalog_images_paisita');
    return saved ? JSON.parse(saved) : {};
  });

  // --- DATOS FINANCIEROS DEL DÍA (Persistencia) ---
  const [ventasDelDia, setVentasDelDia] = useState(() => {
    const guardadas = localStorage.getItem('ventas_paisita');
    return guardadas ? JSON.parse(guardadas) : [];
  });

  const [mermasDelDia, setMermasDelDia] = useState(() => {
    const guardadas = localStorage.getItem('mermas_paisita');
    return guardadas ? JSON.parse(guardadas) : [];
  });

  const [fechaHoy] = useState(() => {
    return new Date().toLocaleDateString('es-CO', { 
      weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' 
    });
  });

  const [sistemaBloqueado, setSistemaBloqueado] = useState(() => {
    const fechaBloqueo = localStorage.getItem('bloqueo_fecha_paisita');
    return fechaBloqueo === new Date().toDateString();
  });

  const [reporteFinalCierre, setReporteFinalCierre] = useState(() => {
    const guardado = localStorage.getItem('reporte_final_cierre_paisita');
    return guardado ? JSON.parse(guardado) : null;
  });

  // --- FORMULARIO ---
  const [nombre, setNombre] = useState('Empanada');
  const [categoria, setCategoria] = useState('Fritos');
  const [tempImage, setTempImage] = useState(null); 
  const [precioCosto, setPrecioCosto] = useState(1500);
  const [impuesto, setImpuesto] = useState('19'); 
  const [precioVenta, setPrecioVenta] = useState(2500);
  const [stock, setStock] = useState(20);

  // --- EFECTOS DE GUARDADO AUTOMÁTICO ---
  useEffect(() => localStorage.setItem('ventas_paisita', JSON.stringify(ventasDelDia)), [ventasDelDia]);
  useEffect(() => localStorage.setItem('mermas_paisita', JSON.stringify(mermasDelDia)), [mermasDelDia]);
  useEffect(() => localStorage.setItem('catalog_images_paisita', JSON.stringify(storedImages)), [storedImages]);

  // --- EFECTO DE CARGA INICIAL ---
  useEffect(() => {
    const fechaBloqueo = localStorage.getItem('bloqueo_fecha_paisita');
    if (fechaBloqueo !== new Date().toDateString()) {
      setSistemaBloqueado(false);
      setReporteFinalCierre(null);
      localStorage.removeItem('reporte_final_cierre_paisita');
    }
    if (isLoggedIn && !sistemaBloqueado) obtenerInventarioBackend();
  }, [isLoggedIn, sistemaBloqueado]);

  // --- INNOVACIÓN 1: MODO FILA VIRTUAL (Atajos de teclado) ---
  useEffect(() => {
    const handleKeyDown = (e) => {
      // Ignorar si estamos en un input o el sistema está bloqueado
      if (e.target.tagName === 'INPUT' || e.target.tagName === 'SELECT' || pantalla !== 'catalogo' || sistemaBloqueado) return;

      const keyIndex = parseInt(e.key, 10);
      if (!isNaN(keyIndex) && keyIndex > 0 && keyIndex <= productos.length) {
        const productoObjetivo = productos[keyIndex - 1];
        if (productoObjetivo.stock > 0) {
          registrarVenta(productoObjetivo);
        }
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [productos, pantalla, sistemaBloqueado]);

  // --- CONEXIÓN BACKEND ---
  const obtenerInventarioBackend = async () => {
    try {
      const respuesta = await fetch('http://localhost:8080/api/productos');
      if (respuesta.ok) {
        const datos = await respuesta.json();
        const datosNormalizados = datos.map(p => ({
          ...p,
          stock: parseInt(p.stock !== undefined ? p.stock : p.cantidad, 10) || 0,
          precioVenta: parseFloat(p.precioVenta) || 0,
          precioCosto: parseFloat(p.precioCosto) || 0,
          impuesto: parseFloat(p.impuesto) || 0
        }));
        setProductos(datosNormalizados);
      }
    } catch (error) {
      console.error("Error al sincronizar con Spring Boot:", error);
    }
  };

  const handleBorrarTodo = async () => {
    if (window.confirm("🚨 ¿ELIMINAR TODOS los productos de la base de datos?")) {
      try {
        const respuesta = await fetch('http://localhost:8080/api/productos/vaciar', { method: 'DELETE' });
        if (respuesta.ok) {
          setProductos([]); setVentasDelDia([]); setMermasDelDia([]);
          localStorage.removeItem('ventas_paisita');
          localStorage.removeItem('mermas_paisita');
          obtenerInventarioBackend();
        }
      } catch (error) {
        alert("Error de conexión.");
      }
    }
  };

  const manejarGuardadoProducto = async (productoActualizado, mensajeExito) => {
    try {
      const respuesta = await fetch('http://localhost:8080/api/productos', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(productoActualizado)
      });
      if (respuesta.ok) {
        if(mensajeExito) alert(mensajeExito);
        obtenerInventarioBackend(); 
      }
    } catch (error) {
      alert("Error de red con Spring Boot.");
    }
  };

  const cambiarStockManual = (producto) => {
    if (sistemaBloqueado) return;
    const nuevoStock = parseInt(prompt(`Modificar existencias de: ${producto.nombre}`, producto.stock), 10);
    if (!isNaN(nuevoStock) && nuevoStock >= 0) {
      manejarGuardadoProducto({ ...producto, stock: nuevoStock }, `Stock actualizado a ${nuevoStock}`);
    }
  };

  // --- INNOVACIÓN 3: REGISTRO DE MERMAS ---
  const registrarMerma = (producto) => {
    if (sistemaBloqueado) return;
    const cantMerma = parseInt(prompt(`¿Cuántas unidades de ${producto.nombre} vas a dar de baja (quemadas/dañadas)?`), 10);

    if (isNaN(cantMerma) || cantMerma <= 0 || cantMerma > producto.stock) {
      alert("Cantidad inválida o superior al stock actual.");
      return;
    }

    const costoRealConIva = producto.precioCosto * (1 + (producto.impuesto / 100));
    const perdidaTotal = costoRealConIva * cantMerma;

    const nuevaMerma = {
      id: Date.now(),
      nombre: producto.nombre,
      cantidad: cantMerma,
      perdida: perdidaTotal,
      hora: new Date().toLocaleTimeString('es-CO', { hour: '2-digit', minute: '2-digit' })
    };

    setMermasDelDia(prev => [...prev, nuevaMerma]);
    manejarGuardadoProducto({ ...producto, stock: producto.stock - cantMerma });
  };

  const handleGuardarFormulario = async (e) => {
    e.preventDefault();
    if (sistemaBloqueado) return;

    const nombreLimpio = nombre.trim();
    if (productos.find(p => p.nombre.toLowerCase() === nombreLimpio.toLowerCase())) {
      alert("El producto ya existe."); return;
    }

    if (tempImage) setStoredImages(prev => ({ ...prev, [nombreLimpio]: tempImage }));

    const nuevoProducto = {
      nombre: nombreLimpio,
      categoria: categoria.trim(),
      imagenUrl: 'https://images.unsplash.com/photo-1628102477218-097561f38e6f?q=80&w=300&auto=format&fit=crop',
      precioCosto: Number(precioCosto), impuesto: Number(impuesto),
      precioVenta: Number(precioVenta), stock: Number(stock)
    };

    manejarGuardadoProducto(nuevoProducto, "¡Producto inyectado!");
    setPantalla('catalogo');
  };

  const registrarVenta = async (producto) => {
    if (sistemaBloqueado || producto.stock <= 0) return;

    try {
      const respuesta = await fetch(`http://localhost:8080/api/ventas/${producto.id}/1`, { method: 'POST' });
      if (respuesta.ok) {
        const costoRealConIva = producto.precioCosto * (1 + (producto.impuesto / 100));

        setVentasDelDia(prev => [...prev, {
          id: Date.now(),
          nombre: producto.nombre,
          precioVenta: producto.precioVenta,
          costoConIva: costoRealConIva,
          gananciaNeta: producto.precioVenta - costoRealConIva,
          hora: new Date().toLocaleTimeString('es-CO', { hour: '2-digit', minute: '2-digit' })
        }]);
        obtenerInventarioBackend(); 
      }
    } catch (error) {
      alert("Error al procesar venta en backend.");
    }
  };

  const limpiarCierreCaja = () => {
    if (window.confirm("¿Cerrar jornada? Se bloquearán ventas y mermas por hoy.")) {
      const reporteFinal = {
        fecha: fechaHoy,
        totalVentas: ventasDelDia.length,
        ingresosTotales,
        perdidasMermas,
        gananciaReal: gananciasTotalesNetas - perdidasMermas,
        detallesTransacciones: [...ventasDelDia],
        top3: topProductos
      };

      localStorage.setItem('bloqueo_fecha_paisita', new Date().toDateString());
      localStorage.setItem('reporte_final_cierre_paisita', JSON.stringify(reporteFinal));

      setReporteFinalCierre(reporteFinal);
      setVentasDelDia([]); setMermasDelDia([]);
      localStorage.removeItem('ventas_paisita');
      localStorage.removeItem('mermas_paisita');
      setSistemaBloqueado(true);
    }
  };

  const formatearMoneda = (v) => new Intl.NumberFormat('es-CO', { style: 'currency', currency: 'COP', minimumFractionDigits: 0 }).format(v);

  // --- CÁLCULOS EN TIEMPO REAL ---
  const ingresosTotales = ventasDelDia.reduce((sum, v) => sum + v.precioVenta, 0);
  const gananciasTotalesNetas = ventasDelDia.reduce((sum, v) => sum + v.gananciaNeta, 0);
  const perdidasMermas = mermasDelDia.reduce((sum, m) => sum + m.perdida, 0);

  // --- INNOVACIÓN 2: TOP 3 PRODUCTOS ESTRELLA ---
  const analisisProductos = ventasDelDia.reduce((acc, v) => {
    if(!acc[v.nombre]) acc[v.nombre] = { nombre: v.nombre, ganancia: 0, cantidad: 0 };
    acc[v.nombre].ganancia += v.gananciaNeta;
    acc[v.nombre].cantidad += 1;
    return acc;
  }, {});
  const topProductos = Object.values(analisisProductos).sort((a,b) => b.ganancia - a.ganancia).slice(0,3);

  // --- RENDERIZADO LOGIN ---
  if (!isLoggedIn) {
    return (
      <div className="login-container">
        <div className="login-card">
          <h2>El Paisita UP</h2>
          <p>Smart Inventory System</p>
          <input type="text" placeholder="Usuario (admin)" value={username} onChange={e => setUsername(e.target.value)} className="login-input" />
          <input type="password" placeholder="Clave (12345)" value={password} onChange={e => setPassword(e.target.value)} className="login-input" />
          <button onClick={() => { 
            if(username === 'admin' && password === '12345') setIsLoggedIn(true); 
            else alert('Credenciales incorrectas');
          }} className="login-btn">Acceder</button>
        </div>
      </div>
    );
  }

  // --- RENDERIZADO SISTEMA BLOQUEADO (CIERRE DE CAJA FINAL) ---
  if (sistemaBloqueado && reporteFinalCierre) {
    return (
      <div className="bloqueo-layout">
        <div className="bloqueo-card" style={{maxWidth: '800px'}}>
          <h2>Caja Cerrada - Reporte de Utilidades</h2>

          <div className="kpi-dashboard" style={{marginBottom: '20px'}}>
             <div className="kpi-card text-pastel-blue">
                <h3>Recaudo Bruto</h3><p className="kpi-valor">{formatearMoneda(reporteFinalCierre.ingresosTotales)}</p>
              </div>
              <div className="kpi-card text-pastel-pink">
                <h3>Pérdidas (Mermas)</h3><p className="kpi-valor" style={{color: '#ff6b6b'}}>-{formatearMoneda(reporteFinalCierre.perdidasMermas)}</p>
              </div>
              <div className="kpi-card text-pastel-green">
                <h3>GANANCIA REAL</h3><p className="kpi-valor">{formatearMoneda(reporteFinalCierre.gananciaReal)}</p>
              </div>
          </div>

          <h3 style={{color: 'white', marginTop: '20px'}}>🏆 Podio: Productos Estrella</h3>
          <div style={{display: 'flex', gap: '10px', marginBottom: '20px'}}>
            {reporteFinalCierre.top3.map((p, i) => (
              <div key={i} style={{flex: 1, background: '#3a2a2a', padding: '15px', borderRadius: '8px', textAlign: 'center', color: '#ffd700'}}>
                <div style={{fontSize: '24px'}}>{i === 0 ? '🥇' : i === 1 ? '🥈' : '🥉'}</div>
                <strong>{p.nombre}</strong><br/>
                <small>{p.cantidad} uds vendidas</small>
              </div>
            ))}
          </div>

          <button className="btn-logout" onClick={() => { setIsLoggedIn(false); setPantalla('catalogo'); }}>Salir</button>
        </div>
      </div>
    );
  }

  // --- APP PRINCIPAL ---
  return (
    <div className="app-layout">
      <header className="app-header">
        <div className="header-brand">
          <h1>El Paisita UP</h1><p className="fecha-badge">📅 {fechaHoy}</p>
        </div>
        <nav className="header-nav">
          <button className={`nav-link ${pantalla === 'catalogo' ? 'active' : ''}`} onClick={() => setPantalla('catalogo')}>📦 Terminal de Ventas</button>
          <button className={`nav-link ${pantalla === 'formulario' ? 'active' : ''}`} onClick={() => setPantalla('formulario')}>➕ Nuevo Producto</button>
          <button className={`nav-link-alert ${pantalla === 'reporte' ? 'active' : ''}`} onClick={() => setPantalla('reporte')}>📊 Analítica & Cierre</button>
          <button className="btn-nav-logout-direct" onClick={() => setIsLoggedIn(false)}>🚪 Salir</button>
        </nav>
      </header>

      <main className="app-content">
        {pantalla === 'catalogo' && (
          <div className="catalogo-view">
             <div style={{marginBottom: '15px', padding: '10px', background: '#3a2a2a', borderRadius: '5px', color: '#aaa', fontSize: '14px'}}>
              💡 <strong>Tip Smart:</strong> Presiona los números del teclado (1 al {productos.length || 'X'}) para vender rápidamente sin usar el mouse.
            </div>

            <div className="grid-catalogo">
              {productos.map((prod, index) => {
                const ventasDeEsteProducto = analisisProductos[prod.nombre]?.cantidad || 0;
                const esAltaDemanda = ventasDeEsteProducto >= 3 && prod.stock <= 10 && prod.stock > 0;

                return (
                  <div key={prod.id} className="card-producto" style={{ border: esAltaDemanda ? '2px solid #ffb3ba' : 'none' }}>

                    <div style={{position: 'absolute', top: '10px', left: '10px', background: 'rgba(0,0,0,0.7)', padding: '5px 10px', borderRadius: '50%', color: 'white', fontWeight: 'bold', zIndex: 2}}>
                      {index + 1}
                    </div>

                    <div className="card-image-wrapper">
                      <img src={storedImages[prod.nombre] || prod.imagenUrl} alt={prod.nombre} style={{ width: '100%', height: '160px', objectFit: 'cover' }} />
                      {esAltaDemanda && <span style={{position: 'absolute', bottom: '5px', left: '5px', background: '#ffb3ba', color: '#5a1a1a', padding: '3px 8px', borderRadius: '4px', fontSize: '12px', fontWeight: 'bold'}}>🔥 Alta Demanda</span>}
                    </div>

                    <div className="card-info" style={{padding: '12px'}}>
                      <h3 style={{margin: '0 0 10px 0'}}>{prod.nombre}</h3>
                      <div style={{display: 'flex', justifyContent: 'space-between', marginBottom: '10px'}}>
                        <span style={{fontSize: '18px', color: '#baffc9', fontWeight: 'bold'}}>{formatearMoneda(prod.precioVenta)}</span>
                        <span style={{color: '#aaa'}}>Stock: {prod.stock}</span>
                      </div>

                      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '8px', marginBottom: '8px' }}>
                        <button className="btn-vender-card" onClick={() => registrarVenta(prod)} disabled={prod.stock <= 0}>
                           🛒 Vender
                        </button>
                        <button className="btn-modificar-stock" onClick={() => registrarMerma(prod)} style={{background: '#ffb3ba', color: '#5a1a1a'}}>
                          🗑️ Merma
                        </button>
                      </div>
                      <button className="btn-modificar-stock" style={{width: '100%', background: '#4a4a4a'}} onClick={() => cambiarStockManual(prod)}>
                        ✏️ Ajustar Inventario
                      </button>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {pantalla === 'formulario' && (
          <div className="form-container-centered">
            {/* El formulario se mantiene igual, ya funcionaba perfecto */}
            <div className="form-card">
              <h2>Inyectar Nueva Mercancía</h2>
              <form onSubmit={handleGuardarFormulario}>
                <input type="text" placeholder="Nombre" value={nombre} onChange={e => setNombre(e.target.value)} className="form-input" required />
                <input type="text" placeholder="Categoría" value={categoria} onChange={e => setCategoria(e.target.value)} className="form-input" required />
                <input type="number" placeholder="Precio Costo" value={precioCosto} onChange={e => setPrecioCosto(e.target.value)} className="form-input" required />
                <select value={impuesto} onChange={e => setImpuesto(e.target.value)} className="form-input">
                  <option value="19">IVA 19%</option><option value="8">INC 8%</option><option value="0">Exento</option>
                </select>
                <input type="number" placeholder="Precio Venta" value={precioVenta} onChange={e => setPrecioVenta(e.target.value)} className="form-input" required />
                <input type="number" placeholder="Cantidad Inicial" value={stock} onChange={e => setStock(e.target.value)} className="form-input" required />
                <button type="submit" className="btn-submit">Guardar Producto</button>
              </form>
            </div>
          </div>
        )}

        {pantalla === 'reporte' && (
          <div className="reporte-view">

            {topProductos.length > 0 && (
              <div style={{background: '#2a1a1a', padding: '20px', borderRadius: '10px', marginBottom: '20px'}}>
                <h2 style={{color: 'white', marginTop: 0}}>🏆 Top 3 Productos Estrella</h2>
                <div style={{display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '15px'}}>
                  {topProductos.map((p, i) => (
                    <div key={i} style={{background: '#3a2a2a', padding: '15px', borderRadius: '8px', borderTop: `4px solid ${i===0?'#ffd700':i===1?'#c0c0c0':'#cd7f32'}`}}>
                      <div style={{color: '#fff', fontSize: '18px'}}>{i+1}. {p.nombre}</div>
                      <div style={{color: '#baffc9', fontSize: '14px'}}>Deja: +{formatearMoneda(p.ganancia)} netos</div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            <div className="kpi-dashboard">
              <div className="kpi-card text-pastel-blue">
                <h3>Ventas Brutas</h3><p className="kpi-valor">{formatearMoneda(ingresosTotales)}</p>
              </div>
              <div className="kpi-card text-pastel-pink">
                <h3>Pérdidas (Mermas)</h3><p className="kpi-valor">-{formatearMoneda(perdidasMermas)}</p>
              </div>
              <div className="kpi-card text-pastel-green">
                <h3>Utilidad Neta Real</h3><p className="kpi-valor">{formatearMoneda(gananciasTotalesNetas - perdidasMermas)}</p>
              </div>
            </div>

            <div className="form-card full-width-card" style={{marginTop: '20px'}}>
              <div className="reporte-header">
                <h2>Cierre Diario</h2>
                <button className="btn-clean-caja" onClick={limpiarCierreCaja}>🔒 Finalizar Jornada</button>
              </div>
              <table className="tabla-reporte">
                <thead><tr><th>Hora</th><th>Ítem</th><th>Ingreso</th><th>Margen</th></tr></thead>
                <tbody>
                  {ventasDelDia.map(v => (
                    <tr key={v.id}>
                      <td>{v.hora}</td><td>{v.nombre}</td>
                      <td>{formatearMoneda(v.precioVenta)}</td>
                      <td style={{color: '#baffc9'}}>+{formatearMoneda(v.gananciaNeta)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

export default App;
